class Evaluation
  attr_reader :matrix, :correct, :total, :micro, :macro

  def self.real(value)
    text = format('%.4f', value)
    text == '-0.0000' ? '0.0000' : text
  end

  def self.rounded_key(value)
    real(value).delete('.').to_i
  end

  def self.two(hundredfold)
    "#{hundredfold / 100}.#{(hundredfold % 100).to_s.rjust(2, '0')}"
  end

  def self.proportion(numerator, denominator)
    "#{numerator}/#{denominator} #{real(numerator.fdiv(denominator))}"
  end

  def self.fraction(numerator, denominator)
    return '- -' if denominator.zero?

    divisor = numerator.gcd(denominator)
    "#{numerator / divisor}/#{denominator / divisor} #{real(numerator.fdiv(denominator))}"
  end

  def initialize(truth, predictions, class_count)
    @matrix = Array.new(class_count) { Array.new(class_count, 0) }
    truth.each_with_index { |actual, index| @matrix[actual][predictions[index]] += 1 }
    @total = truth.length
    @correct = class_count.times.sum { |class_id| @matrix[class_id][class_id] }
    @micro = @correct.fdiv(@total)
    @statistics = class_count.times.map do |class_id|
      [@matrix[class_id][class_id], @matrix.sum { |row| row[class_id] }, @matrix[class_id].sum]
    end
    sum = 0.0
    included = 0
    @statistics.each do |tp, predicted, actual|
      next if predicted + actual == 0

      sum += (2 * tp).fdiv(predicted + actual)
      included += 1
    end
    @macro = sum / included
  end

  def lines(classes)
    result = ["true\\predicted #{classes.join(' ')}"]
    classes.each_with_index { |name, class_id| result << "#{name} #{@matrix[class_id].join(' ')}" }
    classes.each_with_index do |name, class_id|
      tp, predicted, actual = @statistics[class_id]
      result << "class #{name} precision #{self.class.fraction(tp, predicted)} " \
                "recall #{self.class.fraction(tp, actual)} f1 #{self.class.fraction(2 * tp, predicted + actual)} support #{actual}"
    end
    result << "micro_f1 #{self.class.real(@micro)} macro_f1 #{self.class.real(@macro)}"
    result
  end
end

class Vocabulary
  Entry = Struct.new(:term, :df, :chi_square, :best_class)
  Encoded = Struct.new(:sequence, :unique, :counts)
  attr_reader :terms, :ranking, :candidate_count, :all_term_count, :df, :class_counts, :positions

  def initialize(documents, class_count, minimum_df, features, use_bigrams)
    @use_bigrams = use_bigrams
    @class_counts = Array.new(class_count, 0)
    occurrences = Hash.new { |hash, term| hash[term] = Array.new(class_count, 0) }
    documents.each do |document|
      @class_counts[document.class_id] += 1
      document.terms(use_bigrams).uniq.each { |term| occurrences[term][document.class_id] += 1 }
    end
    @df = occurrences.transform_values(&:sum)
    @all_term_count = occurrences.length
    count = documents.length
    candidates = []
    occurrences.each do |term, per_class|
      frequency = @df.fetch(term)
      next if frequency < minimum_df

      best_value = 0.0
      best_class = 0
      class_count.times do |class_id|
        a = per_class[class_id]
        b = frequency - a
        c = @class_counts[class_id] - a
        e = count - @class_counts[class_id] - b
        difference = a * e - b * c
        numerator = count * difference * difference
        denominator = frequency * (count - frequency) * @class_counts[class_id] *
                      (count - @class_counts[class_id])
        value = denominator.zero? ? 0.0 : numerator.fdiv(denominator)
        if value > best_value
          best_value = value
          best_class = class_id
        end
      end
      candidates << Entry.new(term, frequency, best_value, best_class)
    end
    @candidate_count = candidates.length
    candidates.sort_by! { |entry| [-entry.chi_square, entry.term] }
    @ranking = features.positive? ? candidates.first(features) : candidates
    @terms = @ranking.map(&:term).sort
    @positions = @terms.each_with_index.to_h
  end

  def size
    @terms.length
  end

  def encode(document)
    sequence = document.terms(@use_bigrams).filter_map { |term| @positions[term] }
    counts = sequence.tally
    Encoded.new(sequence, counts.keys, counts)
  end
end
